            "text": "A. Read the advertisement for the Global Youth Magazine's competition.\nWould you like to go? Why/Why not?\n\nGLOBAL YOUTH MAGAZINE (GYM)\nTell us about yourself and win a chance to join the editorial team on a road trip around Europe, starting in ... LONDON!\nAre you a writer, a designer, a reporter, a photographer, an editor? Are you interested in the world around you? Do you want to learn from people in lots of different countries?\nFill out the application form below and maybe, just maybe, we'll see you in London.\n(Applicants should be between the ages of 14–17 and available between the 15th June–1st August.)\n\nRoute: London -> Stonehenge -> Paris -> Munich -> Alps -> Venice\n\nName: Jad Aziz Ali\nAge: 15\nAddress: 319, 2, 14, Um Qasr, Basra, Iraq\nTell us about your experience of working on magazines: I've always been very interested in photography. I have worked on the school magazine for three years. Last year, I won the Young Photographer Award here in Iraq.\nWhy do you want to join the GYM team? I want to learn about young people around the world. I believe that by sharing our pictures we can understand each other a little better.\nWhich other countries have you been to? I have been to Canada.\nWhich languages do you speak? I speak Arabic, English and a little French.\nWhat do you do in your spare time? I really enjoy canoeing and rowing. I love anything connected to the water. But I always have my camera with me."
