            "page": 17,
            "heading": "Lesson 1: Keep fit!",
            "text": "A. Read the article. What is each paragraph about?\n\nTake my advice ...\nFitness is very important. Unfit people cannot enjoy life. They get tired very quickly, so they cannot play games. They cannot run. In fact, they cannot even walk without getting tired and out of breath. So, if you want to enjoy life, you should get fit and keep fit.\nHow can you get fit? You should take exercise regularly. Games like football, basketball and netball give you plenty of exercise because you have to run all the time. Swimming and cycling are also very good forms of exercise. If you don't like any of these, you can just go walking. You should walk quickly for about 20 minutes every day. Walking slowly will not make you fit and walking to your bedroom will not either! Some people think that taking exercise is boring, but it doesn't have to be. If you take exercise with your friends, you will have fun.\n\nB. Give advice to the people who are unfit.\nYou should ...\n\nGiving advice with should\nYou need to get fit. You should take some exercise.\nYou're always tired. You shouldn't go to bed late.\n\nWhich of the people do you think is fit?\n1. Zaid: \"They won't let me play. I get tired quickly.\"\n2. Sana: \"I watch TV all the time.\"\n3. Hanaa: \"I love running.\"\n4. Younis: \"I love my car. I drive everywhere.\""
