            "text": "A. Listen and look at the pictures.\n1. Ansam   2. Anas   3. Jameel   4. Noora\n\nB. Now match the sentences to the pictures.\na. I have a stomach ache.\nb. I have an earache.\nc. I've got a toothache.\nd. I've got a headache.\n\nAches\nWe can say I've got a headache. OR My head aches. They mean the same thing.\n\nC. Listen and read. Then read the conversations aloud.\n• What's the matter, Ansam?\n• I've got a toothache.\n• Oh, dear! You should go to the dentist.\n• Yes, I will.\n\n• What's wrong, Anas?\n• I have a stomach ache, and I feel sick.\n• You shouldn't eat so many crisps in the break.\n• Yes, I think you're right.\n\n• Are you all right, Jameel?\n• No, my ear hurts.\n• Oh, I'm sorry. You should go to the doctor.\n• I've been to the doctor. He gave me some drops. I have to put them in twice a day.\n\n• You don't look well, Noora.\n• I've got a bad headache.\n• Oh, dear. Here, take these two pills with some water.\n• Thanks very much.\n\nWhat do you think of the advice the woman gives the children?\n\nD. Now make up your own conversations."
