            "heading": "Lesson 7: A letter",
            "text": "A. Read the letter.\nSara's friend is in hospital. She wrote her a letter and put it inside the card.\n\n411, 36, 7\nKarrada\nBaghdad\n4th March 2021\n\nDear Muna,\nI was very sorry to hear about your accident. I hope your leg does not hurt too much and that you will be able to leave hospital soon.\nWe have had an unusual week at school. First, we had a visit from a nurse called Janette. She gave us a talk about food. It was very interesting, and I really enjoyed it. Now I can tell you which food is good for you and which is not so good. Then, we had a visit from a netball coach. She was fantastic. We learnt a lot from her. She showed us little things to make our game better. I will show them to you when you are back at school.\nAll your friends in class miss you and send you their best wishes. We will come and see you on Friday if you are still in hospital.\nLove,\nSara\n\nB. Answer the questions with your partner.\n1. Why did Nurse Janette visit the school?\n2. What advice do you think Nurse Janette gave the students?\n3. Why did the netball coach visit the school?\n4. Why might Friday be a good day for Muna?\n5. Imagine you are Muna. Think of one good thing and one bad thing about being in hospital."
