            "heading": "Lesson 5: The Olympic Games",
            "text": "A. Read about the Olympic Games.\n\nOLYMPIC FACTS AND FIGURES\nThe old Olympic Games took place in Greece 2,000 years ago. In 1896, a Frenchman, Pierre de Coubertin, started the modern Olympic Games. They take place every four years, in a different city each time.\nPierre de Coubertin thought that everybody should enjoy taking part in the Games. He said, 'The most important thing in the Olympic Games is not to win, but to take part.'\nMore than 200 countries took part in the Rio de Janeiro Olympic Games in 2016. Athletes from 87 countries won medals. The athletes competed in 28 different sports.\nThe athletes who come first, second and third win medals. The winner gets a gold medal, the athlete who comes second gets a silver medal, and the third gets a bronze medal.\nThe rings on the Olympic flag show the meeting of athletes from all over the world. The five colours and the white background are the only six colours that were on national flags in 1913, when the Olympic flag was invented.\n\nB. Ask and answer the questions.\n• What do the athletes who come second get?\n• How many countries took part in the Olympic Games in 2016?\n• What do the Olympic rings stand for?\n• Who was Pierre de Coubertin?\n• Did de Coubertin think it was important to win in the Olympic Games?\n• When were the first modern Olympic Games held?\n• How often do the Olympic Games take place?"
