            "text": "A. In this unit, you have practised:\n\n1. Talking about which sports you would like to do or play\n• What sports would you like to do?\n• I'd like to play tennis.\n• I'd like to do athletics.\n\n2. Asking and answering questions about a timetable\n• When is the advanced horse riding class?\n• On Saturday, from three o'clock to five o'clock in the afternoon.\n\n3. Asking and answering questions about how good people are at sport\n• How good are you at volleyball?\n• I'm quite good, but I'd like to practise.\n• I've never played volleyball. I'd like to learn.\n\n4. Saying numbers and years\n• 28.28 seconds: twenty-eight point two eight seconds\n• 1996: nineteen ninety-six\n• 2015: two thousand and fifteen\n\n5. Describing changes\nI used to have no friends, but now I have lots.\nI used to be lazy, but now I work hard.\n\n6. And you have ...\n• used information from conversations to fill in a timetable.\n• performed a conversation.\n• written sentences to make a story.\n• practised finding information quickly in texts.\n• found new words and worked out their meanings as you read.\n• written a paragraph."
