            "text": "Remember! Listening can be hard work. You have to do it yourself. Nobody else can do it for you.\n\nA. Read the Listening tips.\n\nListening tip 1 – Look and listen for clues.\nThink about what you have to listen for. Are there any clues in the title, in the pictures, in the questions? If not, listen for clues in the text itself.\n\nB. Listen to two conversations.\nWhere are the people in each conversation? What are they doing?\n\nListening tip 2 – Keep listening!\nIf you don't understand a word or miss something, keep listening. Perhaps you can guess the word. Perhaps you don't need to know the meaning.\n\nC. You want to know the score in a football match between Iraq and Bahrain. Listen to the radio.\n'And now, sport. At the end of an exciting game at the new National Stadium, the score was ...'\n\nListening tip 3 – Write notes.\nWhen you have to listen and write answers, you don't have time to write sentences. You need to write notes first and write the complete answer later. Make your own abbreviations. Make sure you can understand them later!\n\nD. Work out the student notes below. Then listen and check.\n1. What did Mr Andrews order?   fr. chick. – r. + sal. – choc. c. – app. ju.\n2. What did Mrs Andrews order?  gr. fish – frs. + sal. – fru. sal. – min. wat."
