            "page": 45,
            "heading": "Lesson 3: Speaking",
            "text": "Practice makes perfect. You will only improve your speaking if you practise. When you practise, try to remember the following tips.\n\nA. Read the Speaking tips.\n\nSpeaking tip 3 – Reading aloud\nWhen you read aloud, remember the following:\n• You want someone to hear you, so always speak clearly.\n• Try to pronounce words as you have heard them on the audio.\n• Don't stop after each word. We say words in groups, so when you are saying a word, your eyes need to be on the words that come after it.\n\nB. Listen and read the sentences aloud.\n1. It's very hot today.\n2. It was very hot and windy yesterday.\n3. It was very hot and windy when we went to the beach last weekend.\n\nSpeaking tip 4 – Asking questions\nWhen you ask questions beginning with question words, your voice goes down at the end. Question words are:\nWhat? Why? Who? When? How? Which?\nWhen you ask other questions, your voice goes up at the end.\n\nC. Listen to the conversations. Then read them aloud.\nThe strongest parts of the sentences are underlined. The arrows show where your voice goes up or down.\n\nConversation 1:\n• How are you? You look tired.\n• I feel awful, and I have a headache.\n• Have you been to the doctor?\n• No. I'll go this afternoon.\n\nConversation 2:\n• Can I help you?\n• When do you have swimming lessons?\n• Are you good at swimming?\n• No. I'm a beginner.\n• The beginners' class is at ten o'clock on Saturday morning."
