            "page": 48,
            "heading": "Lesson 2: Accessing information",
            "text": "A. Answer the questions with a partner.\n1. How often do you use a library?\n2. What was the last book you used from a library?\n3. How often do you use the internet?\n4. How do you usually access the internet?\n\nB. Read and choose the best summary.\n\nNowadays, we have access to huge amounts of information. You can use an encyclopedia in the library if you want to find out about Saladdin. If you want to know what the capital of Madagascar is, you can look it up in an atlas. (Do you know the answer?) Or you can go straight to the internet for all the answers. There is an incredible amount of information on the internet. However, remember a lot of information does not always mean good information. We always need to think critically about what we're reading. Who wrote the information? And most importantly, why did they write it? Can we find the same information in different sources? Are there any references we can check? Many websites check all the details carefully to make sure they're correct. Sadly, many websites aren't interested in the truth and just want as many readers as possible.\n\n1. The information in books is always correct.\n2. The information on the internet is always correct.\n3. It's good to ask questions about everything we read.\n\nC. What information can you get from the following?\n1. newspaper   2. dictionary   3. radio\n\nD. Discuss in pairs. You need information about the things in the box. Where can you find it?\n• how to grow plants   • a big world event   • the time of sunset\n• the population of India   • when the museum is open   • the meaning of 'encyclopedia'"
