            "text": "A. Read the Reading tip.\n\nReading tip 6 – Dictionaries\nWe need dictionaries to find the meanings of words and to check their spelling.\nRemember:\n1. All the words in a dictionary are in alphabetical order. To find a word quickly, you need to know the alphabet very well.\nWho can put the words below into alphabetical order the fastest?\n[bus | bag | book | boy | bicycle | blue | bright | but | box | belt | build | better]\n\n2. It is also important to know the meaning of the abbreviations below.\n[(n.)  (v.)  (adj.)  (adv.)  (pron.)  (prep.)  (conj.)]\nWork out what the abbreviations mean. Then find an example of each in the sentence below:\nThe black horse ran fast, so it won the race easily.\n\n3. A word can have more than one meaning, and you will find all of them in a dictionary. It is important to choose the correct meaning.\n\nB. Read the dictionary entry. Find the correct definition for 'bank' in each of the sentences a–d. Is it a noun or a verb?\n\nbank (n.) 1. a place where you keep money. 2. a piece of ground higher than the ground around it. 3. a piece of ground next to a river. 4. a piece of ground, usually sand or rock, in the sea, near or above the top of the water.\nbank (v.) 5. to keep money in or put money into a bank. 6. to turn a plane left or right.\n\na. He sat on the grassy bank and put his feet in the water.\nb. The plane banked to the left as it got near the airport.\nc. He wanted to see better, so he walked to the top of the bank.\nd. She banks her money twice a week.\n\nDo you have an English learner's dictionary? If not, see if you can get one, or check out learner's dictionaries on the internet."
