            "text": "A. Read the text and look at the pictures. How long does it take for an article to get from a reporter in Cairo to a reader in Baghdad?\n\n1. On Monday morning, an article is written in Cairo.\n2. Next, it is sent by email to a newspaper office in Baghdad. This takes less than a minute.\n3. When the article arrives, it is read by an editor.\n4. If the editor likes the article, it is edited and inserted into the newspaper."
