            "id": 538,
            "page": 51,
            "heading": "Lesson 5: From Cairo to Baghdad (Part B)",
            "text": "5. Then, it is sent to the printing press, and at night, the newspapers are printed.\n6. Early on Tuesday morning, the newspapers are sent to the shops.\n7. When the shops open, the newspapers are sold.\n8. Finally, the article is read!\n\nActive and passive\nA reporter writes an article in Cairo. (active)\nAn article is written in Cairo. (passive) — Notice we don't need to add 'by a reporter'.\n\nNext, she sends it to Baghdad. (active)\nNext, it is sent to Baghdad. (passive)\n\nWhen we say what people and things do, we use active verb forms like write and send. When we say what happens to people and things, we use passive verb forms like is written and is sent.\nTo form the present passive, use the verb be + past participle of a verb.\nBooks are sold in Al Mutanabbi Street.\nFind more passive verbs in the text. Are there any active ones?\n\nA. Reread the story. Ask and answer questions about it."
