            "id": 540,
            "page": 53,
            "heading": "Lesson 7: Telephones",
            "text": "Look at the photographs. Which of these kinds of telephones have you used?\n1. landline phone   2. mobile phone\n\nA. Read the texts. Find the advantages and disadvantages of each kind of phone.\n\nA landline phone sends and receives signals through a wire. The wire is called the landline. All landlines are connected, so you can phone people all over the world. Landline phones are less useful than mobile phones, because they can only be used in one place. However, they are often more reliable.\n\nA mobile phone does not need a landline because it sends signals to a special mast, using radio waves. The mast sends the radio waves to another phone. There are mobile phone masts in most places, so mobile phones can be used almost anywhere. Many mobile phones can also be used to take photographs, play music and access the internet. These are called 'smartphones'.\n\nPresent passive with can\nLandline phones can be used in one place.\nMobile phones cannot be used without batteries."
