            "heading": "Lesson 2: Two jobs",
            "text": "Lesson 2: Two jobs\n\nA. Read the two paragraphs. Find the words 1–5 and match them to their meanings a–e.\n1 hard-working | 2 university, college | 3 to study | 4 subjects | 5 clever\na things you learn at school\nb places to study\nc the opposite of 'lazy'\nd to spend time learning about something\ne quick to learn and understand\n\nDr Salwa works in a hospital. She takes care of sick people and makes them better. She is very hard-working. She usually works eight hours a day, but she sometimes has to work 12 hours. At school, she was very clever and good in all subjects. After school, she went to university. She had to study for six years. She likes being a doctor because in this job she can help people.\n\nHanan is an office manager. She answers phone calls, and she sends and receives emails on a computer. She usually works every day from 8 a.m. to 2 p.m., but she sometimes has to work in the afternoon. Sometimes she has to go to different countries. Her best subjects at school were Maths and English. After school, she went to college to study Business Administration. She had to study for four years. She enjoys her job because she meets a lot of different people. She also enjoys travelling."
