            "text": "Lesson 4: What's my job?\n\nA. Read the instructions for playing games.\n\nGame A\nStudent 1: Think of a job, but don't tell anyone what it is.\nStudent 2: Ask your partner up to five 'yes' or 'no' questions to try to find out what the job is.\n- Do you help people? | Yes.\n- You're a doctor. | No. Wrong.\n\nGame B\nStudent 1: Write the name of a job on a piece of paper and put it on your partner's back.\nStudent 2: Ask questions to try to find out what the job is.\n- Do I work at night? | Sometimes.\n- Is my job dangerous? | Yes.\n- I'm a firefighter. | Yes. Correct.\n\nGame C\nStudent 1: Think of a job and five things you can say about it.\nStudent 2: After each sentence, try to guess what the job is.\n- I work outside.\n- No. I don't wear a uniform. | You're a police officer.\n\nB. Listen and answer the questions.\n1 Which of the three games do you hear?\n2 Which of the jobs in the box do you hear?\n3 Which ones are not in the box?\n\narchitect | artist | bus driver | cook | doctor | editor | engineer | farmer | firefighter | mechanic | nurse | park-keeper | photographer | pilot | police officer | reporter | secretary | shepherd | shop assistant | singer | teacher\n\nC. Now play the games."
