            "text": "Lesson 7: Career plans (Part A)\n\nA. Read Sara and Adel's plans and answer the questions.\n1 Who thinks they are\n  a friendly?\n  b hard-working?\n  c patient?\n2 Who is good at\n  a Biology?\n  b French?\n  c English?\n3 What job do you think Sara and Adel want to do when they're older?\n\nSara\nI'm 14 years old. I think I'm quite friendly and hard-working. I passed all my exams last year. At school, I'm good at languages. I'm very good at English and French. I'm not very good at Science. When I finish school, ...\n\nAdel\nI'm very hard-working and patient. I have two little brothers, and they never make me angry. At the weekend, I always go and help on a friend's farm because I love working with animals. I enjoy working with horses most. At school, I'm good at Biology. I'm going to take my last school exam next year. If I get good marks, ..."
