            "heading": "Lesson 8: Career plans (Part B)",
            "text": "Lesson 8: Career plans (Part B)\n\nA. Read Khalid and Dania's plans and answer the questions.\n1 Who thinks they are\n  a friendly?\n  b fit and healthy?\n  c good at making things?\n2 What job do you think Khalid and Dania want to do when they're older?\n\nKhalid\nI think I'm quite friendly. At school, I'm good at Maths, but I'm not very good at the other subjects. However, I'm very good at making things. We have a lesson in Woodwork twice a week, and I love it. I make things at home as well – tables, shelves and cupboards.\n\nDania\nI'm very hard-working. I'm also very fit and healthy because I do a lot of sport. My favourite school subjects are Science and IT. I'm also very good at Geography and English. After school, I'm going to study Science at university. When I finish studying, I'm going to fly to the Moon in a spacecraft.\n\nTalking about the future with when\nWhat are you going to do (future) when you finish (present) school?\nThis sentence is about the future, but we always use the present tense in the when part of the sentence.\n\nB. Talk to your partner about your career plans."
