            "text": "Lesson 3: Animals in danger (Part A)\n\nA. Read about the animals and find two reasons why they are in danger.\n\nSnow leopard\nThe fur of this beautiful animal is grey with biggish black spots and much smaller spots. Nobody knows exactly how many there are, but there are very few. It's hunted for its fur.\n\nIbex\nThis mountain goat is hunted for its horns. They are 70 to 140 centimetres long. Its coat is reddish brown to greyish brown. If it's not protected, it'll soon disappear.\n\nBlue whale\nThis is the largest animal alive today. It's 29 metres long. Whales were hunted for their oil and almost disappeared. Now they're protected.\n\nGolden toad\nThe male is bright gold in colour. The female is much darker. People are draining water from the places where they live. When the water goes completely, the golden toad will disappear.\n\nPolar bear\nPolar bears live on sea ice in one of the coldest environments on Earth. Their white coat is very thick and covers a lot of fat which keeps them warm. Polar bears were hunted for the fur, but now they're in more danger because the sea ice is melting as a result of climate change."
