            "text": "Lesson 5: Please keep the rivers clean\n\nA. Read the text and match the paragraphs to the topics.\na What needs to be done | b Water in Iraq | c The solution | d Water pollution in rivers\n\n1 Iraq, with its two great rivers running the length of the country, is unable to provide drinking water for most of its people. There are a lot fewer fish than there were before.\n\n2 The two rivers are polluted with sewage, rubbish and industrial waste. Millions of tonnes of waste go into the rivers and streams every year. This destroys the natural habitats of the wildlife and damages our beautiful rivers. It also causes huge damage to health.\n\n3 The river water must be safe for drinking, fishing, swimming and boating. We can make our rivers safer and healthier for wildlife and people. In fact, everyone should do something to keep the rivers clean. First, we must stop littering. We can make teams of volunteers to pick up the rubbish along the banks. The river will clean itself if we stop littering. Then, we can also lead river clean-up efforts. People can force the government to do something to stop sewage and waste from factories, hospitals and power stations flowing into the rivers.\n\n4 Remember – you are the solution to river pollution. If we want to have clean rivers, we must have clean minds.\n\nB. Find words in the text that match the definitions.\n• a person who does a job without pay\n• to drop rubbish\n• to add harmful things to water, etc.\n• places where animals live"
