            "heading": "Lesson 8: The moving desert",
            "text": "Lesson 8: The moving desert\n\nA. Read the newspaper article and answer the questions.\n1 What are the main causes of the moving desert?\n2 What is the good news?\n\nTHE MOVING DESERT\nThe moving desert is a danger from which many countries around the world suffer. It is caused by social, political, economic or natural factors. It harms both the environment and the people who live there. It damages all aspects of life and is a challenge to many in Iraq.\nThousands of donams* in Iraq are lost every year as a result of the moving desert. This causes many problems to the environment, the economy and society. Moving sand dunes are one of these problems. Sand storms, low rainfall, tree cutting and burning oil wells have all made many parts of Iraq a dry zone. Many fertile areas have disappeared. The desert is moving and expanding. This is happening in Al Anbar, west Karbala, west Muthanna, west Nasiriya and west Basra.\nOne way to stop the moving desert in Iraq is to start 'green belt' projects. There are two projects already, in west Al Anbar and west Karbala.\nThe marshes in the south were drained in the 1990s, and very few plants survived. The wetlands turned into dust, which moves when it is blown by the wind – a moving desert. Today, the marshlands tell a different story, and the picture is improving. Fresh water now flows into some of the dry areas, and as a result, the wildlife is beginning to return. Much of the land is now covered with water, as it was many years ago.\n\n* A donam is a unit of land area equivalent to 2,500 m².\n\nB. Talk about the questions.\n• What do you think will happen if people don't do anything?\n• What happens to the wildlife when the desert moves?\n• Think of more 'green belt' projects. What else would help?"
