            "text": "Lesson 2: Speaking\n\nReading aloud\nRemember:\n• When you're reading aloud, don't stop after each word. We say words in groups, so when you are saying a word, your eyes need to be on the words that come after it.\n• Try to show how the speaker feels.\n\nA. Practise reading the speech bubbles aloud. Then listen carefully. Do you need to practise saying them again?\n- \"I went to a new restaurant last night, but it was awful. The food was bad, and the waiters were very slow. Worst of all, they weren't even polite.\"\n- \"I went to a new restaurant last night, and it was fantastic! The food was delicious, and the waiters were really good. They were helpful and friendly.\"\n\nB. Listen. Then play a game: Going on holiday.\n1 I'm going to take a toothbrush.\n2 I'm going to take a toothbrush and toothpaste.\n3 I'm going to take a toothbrush, toothpaste and sunglasses.\n4 I'm going to take a toothbrush, toothpaste, sunglasses and a guidebook.\n5 I'm going to take a toothbrush, toothpaste, sunglasses and a pair of shoes.\n6 You forgot the guidebook, so we have to start again.\n\nC. Imagine you want one of the jobs. Make phone calls.\nLook back at Making telephone calls on page 54 first.\n\nGarden help wanted.\nSchoolgirl or schoolboy once a week for 2 or 3 hours.\nTel: 327 444\n\nPlay with my children!\nMother wants afternoon help with children aged 5, 7 and 9. Lovely garden and lots of toys.\nTel: 596 369"
