            "text": "Lesson 3: Reading\n\nA. Read the text quickly and find out what each paragraph is about.\n\nTopic sentences\nRemember to look for topic sentences.\n\nA HIGH-FLYING JOB\nMuhammad has always wanted to be a pilot. When he was a little boy, he played with toy planes when other boys played with their cars and trains. He used to sit in the garden and look up at the sky, waiting for a plane to pass over his head. His father sometimes took him to the airport to see the planes.\nMuhammad did very well at school. He worked hard at everything, but especially at Maths and English because he needed these subjects to be a pilot. He knew that English is the 'language of the air', so he did a lot of extra work on English in his spare time. Muhammad got top marks in his final school exams, and he was able to go to an aviation college in Germany to train to be a pilot.\nMuhammad will never forget his time at the college or the people he met there. On the day when he took off on his first solo flight, he was a little nervous, but he was also excited to be flying a plane by himself. 'It was really exciting,' he told his friends afterwards. Muhammad also had to take written exams, which were very difficult. However, he passed them all. 'The day I got my pilot's certificate was the best day of my life,' he said.\n\nB. Now read more carefully and work out the meaning of the words and phrases:\n• especially\n• language of the air\n• extra\n• aviation college\n• solo\n• pilot's certificate\n\nClues\nRemember to look for clues in the sentence or in other sentences.\n\"I think 'aviation college' must mean ________ because ...\""
