            "heading": "Lesson 4: Writing (p. 89)",
            "text": "Lesson 4: Writing\n\nAt the end of the year, is your writing better than it was at the beginning? Do you have any problems? What are you doing about them?\n\nA. Read Writing tips 7 and 8.\n\nWriting tip 7 – Spelling\nYou have to learn how to spell words for yourself. Try this:\n• Look at five words in a list every night.\n• Spell them aloud.\n• Ask somebody to test you.\nPractise writing difficult words:\nExample: friend\n\nWriting tip 8 – Punctuation\nCan you answer the questions easily and correctly?\n1 When do you need to use these?\n• capital letters • full stops • question marks • apostrophes • speech marks\n2 You also need to use commas sometimes. When?\n\nB. Write the sentence with the correct punctuation.\nyouve done well in maths english and arabic my mother said but what about history your mark is very bad\n\nWriting tip 9 – Grammar\nWhen you are checking your draft, look at the verbs and ask yourself these questions:\n1 Am I writing about the present, the past or the future?\nUse these words and phrases to check: yesterday, last week, tomorrow, now\n2 Is this the right part of the verb?\n\nC. Complete the text. Use the correct form of the verbs in brackets.\nI (live) live in Ranya, but my best friend (live) ... in Sulaymaniyah. His family (move) ... there last year. We (like) ... to meet at weekends. Last Friday, we (go) ... to the mountains with my friend's parents. When we (climb) ..., a little boy (go) ... to the edge of the cliff and nearly (fall) .... My father (save) ... him. The little boy said, 'I must be more careful.'\n\nWriting tip 10 – Joining words\nUse joining words to show how your thoughts fit together.\n\nWriting tip 11 – Adjectives and adverbs\nUse adjectives and adverbs to paint a picture. This will make your writing more interesting."
