            "heading": "Transcripts: Unit 1 (Lesson 7, Story time & Project 1, p. 91)",
            "text": "Unit 1 Transcripts (continued)\n\nInterviewer: Do you have any suggestions for making the town better?\nMr James: There are too many cars in the town centre. Why don't they build a ring road?\n\nLesson 7 Embarrassing moments\nC. Listen and check your answers.\nStory 1: 1a, 2f, 3e, 4b, 5d, 6c, 7g\nStory 2: 1a, 2g, 3b, 4e, 5c, 6d, 7f, 8h\n\nC. Listen and check your answers.\nLiz: One day last week, my mum and I were out shopping in town. We were looking for a present for my uncle, so we went to a gift shop. Mum saw a really nice mug on the shelf. 'That's nice,' she said. 'Your uncle will like that. He drinks lots of tea.' I picked it up to look at the price and spilt hot coffee all over my dress. It was the shop assistant's own mug! I was so embarrassed that I nearly died!\nWendy: Last week, my dad took my sister and me to the museum. We were looking at an old car, and I wanted to ask Dad something. I turned round, but he wasn't there. 'Dad! Dad!' I shouted. I was worried. Suddenly, I saw him and ran towards him. Bang! I ran into a big mirror. I still have a black eye. I feel embarrassed every time I go out.\n\nStory time Jad and Johnny – A tour of London\nA. Listen, read and find out.\nFor the story text, see pages 13–14.\n\nProject 1 My first day at school\nD. Read about Adam and Rawan's first day at school. Complete the texts using words from Exercises B and C. Listen and check.\nAdam: Monday was my first day at school. My first lesson was Maths, and my teacher was Mr Hassan. He wrote some questions on the board. They were difficult, and we couldn't use our calculators! I sat next to my new friend, Ali. He's a friendly boy. After Maths, we had a break, and I ate a snack. Then we had my favourite subject – PE! We played football today, and my team won.\nRawan: My first lesson was Geography, and my teacher was Mrs Noor. She pointed to a map on the wall and told us about the different countries. There are 36 students in my class, but I don't know all their names yet. After lunch, we had English. The teacher gave us a test to check our English level. I'm good at English, and so it was easy for me. Then she gave us some homework to do at the weekend. We have to write an essay about our first day at school!"
