            "heading": "Transcripts: Unit 2 (Lessons 3 & 4, p. 92)",
            "text": "Unit 2 Healthy lifestyle\n\nLesson 3 In a restaurant\nB. Now listen and check your ideas.\nWaiter: Good evening.\nFather: Good evening.\nWaiter: Are you ready to order, sir?\nFather: Er, are you ready, Meena? Waleed?\nChildren: Yes, Dad.\nFather: Yes, thank you. Meena, give the waiter your order.\n\n1. Listen. What do the family order? Write M for Meena, W for Waleed and F for father.\nMeena: I'd like a baked potato, please.\nWaiter: A baked potato. And some meat or fish?\nMeena: No, thank you. I'm not very hungry.\nFather: How about a pizza?\nMeena: No, thanks, Daddy. But I'd like a salad, please.\nWaiter: A mixed salad? With tomatoes, lettuce and onions?\nMeena: Oh, yes. That sounds lovely. And can I have a little butter on the baked potato, please?\nWaiter: Yes, of course, miss. And for dessert?\nMeena: I'd like some fruit salad and a little ice cream, please.\nWaiter: Fruit salad and ice cream. And what would you like to drink?\nMeena: Oh, er, I forgot about a drink ... An orange juice, please.\nWaiter: One orange juice. Thank you, miss.\nFather: Now you, Waleed.\nWaleed: Well, I am hungry. I'd like a large burger and fries, please. And ...\nWaiter: One burger and fries.\nFather: You should have some vegetables, Waleed.\nWaiter: The burgers come with a small salad, sir.\nFather: Oh, fine.\nWaleed: And for dessert, I'd like a large piece of chocolate cake and a lot of ice cream.\nFather: Not too much ice cream.\nWaiter: Chocolate cake and ice cream – not too much. And to drink?\nWaleed: Can I have a large cola, please?\nWaiter: One large cola. Thank you. And what would you like, sir?\nFather: I'd like some grilled fish and rice, please, with, let me see, ...\n\nLesson 4 Aches and pains\nA. Listen and look at the pictures.\nAnsam: I've got a toothache.\nAnas: I have a stomach ache.\nJameel: I have an earache.\nNoora: I've got a headache.\n\nC. Listen and read. Then read the conversations aloud.\nWoman: What's the matter, Ansam?\nAnsam: I've got a toothache.\nWoman: Oh, dear! You should go to the dentist.\nAnsam: Yes, I will.\n\nWoman: What's wrong, Anas?\nAnas: I have a stomach ache, and I feel sick.\nWoman: You shouldn't eat so many crisps in the break.\nAnas: Yes, I think you're right.\n\nWoman: Are you all right, Jameel?\nJameel: No, my ear hurts.\nWoman: Oh, I'm sorry. You should go to the doctor.\nJameel: I've been to the doctor. He gave me some drops. I have to put them in twice a day.\n\nWoman: You don't look well, Noora.\nNoora: I've got a bad headache.\nWoman: Oh, dear. Here, take these two pills with some water.\nNoora: Thanks very much.\n\n2. Listen and answer the questions. Write notes. These girls are sick. They have gone to see a doctor.\nDoctor: Hello, Noora.\nNoora: Hello, doctor.\nDoctor: Now, what's the matter?\nNoora: I have a pain in my ear. It really hurts.\nDoctor: So you've got an earache. I'd better have a look. Let me see. Mmmm! Yes, I see. I'll put some drops in your ear. It will be better soon.\nNoora: Will it hurt?"
