            "heading": "Transcripts: Unit 2 (Lesson 4 cont. & Lesson 8, p. 93)",
            "text": "Unit 2 Transcripts (continued)\n\nDoctor: No, of course not. It will feel cold, that's all. Just put your head on one side, please. Thank you. One, two drops. There. That didn't hurt, did it?\nNoora: No, it didn't.\nDoctor: Right. Now take this bottle with you and put two more drops into your ear before you go to bed tonight.\nNoora: Two drops at night.\nDoctor: That's right. Use the drops twice a day until your ear doesn't hurt anymore.\nNoora: How long will it hurt, doctor?\nDoctor: Oh, only a few days. Don't worry. I'm sure your ear will be fine. But don't go swimming until it's better.\nNoora: All right, doctor. Thank you.\nDoctor: Goodbye.\n\n(Pause)\nDoctor: Hello, Rasha. What can I do for you?\nRasha: I've got a very bad headache, doctor. It hurts all the time.\nDoctor: A headache. I see. Your eyes look a bit red, too. Tell me, Rasha, do you wear glasses?\nRasha: Yes, sometimes.\nDoctor: But you're not wearing them now. Why not?\nRasha: I don't like wearing them, doctor. I don't look nice with glasses.\nDoctor: Well, you should wear them all the time, Rasha. If you don't, you'll have headaches all day, every day – and night. And your eyes will get worse. You don't want that to happen, do you?\nRasha: No, I don't, doctor. Do I have to wear them when I'm watching television?\nDoctor: Yes, of course. I said all the time. Except when you're sleeping, of course.\nRasha: All right, doctor.\nDoctor: Good girl. I'll give you some painkillers to stop this headache, but I don't want to hear that you ever have a headache again. Do you understand?\nRasha: Yes, doctor.\nDoctor: There are 12 pills in this box, Rasha. Take two with water, three times a day – today and tomorrow.\nRasha: Two pills, three times a day – today and tomorrow.\nDoctor: That's right. Have you got your glasses with you?\nRasha: Yes, I have.\nDoctor: Good. Put them on now, please, and don't take them off until you go to bed.\nRasha: All right, doctor. And thank you.\nDoctor: Goodbye, Rasha.\nRasha: Goodbye, doctor.\n\nLesson 8 Limericks\nA. Listen and read. Then complete the rules below.\nThere once was a girl from Peru\nWho was trying to paint her roof blue.\nShe felt a bit faint\nAnd spilt all the paint,\nSo now she'll be needing shampoo!\n\nThere was a young man from Tibet\nWho had an incredible pet.\nHe found out its wings\nWere held on with strings,\nAnd now he is very upset.\n\n2. Listen and check.\nI once met a spider in a corner,\nWho said it was getting cooler and cooler.\nI turned up the heat.\nIt worked like a treat,\nAnd now the spider is warmer.\n\nOne day, I was talking to a chicken.\nIt said it wanted to be a pigeon.\nIt wanted to fly.\nDon't ask me why.\nIt ended up in the kitchen.\n\n4. Now listen and check your answers.\nThere was a young boy from Kuwait\nWho got to school every day late.\nWhen his teacher asked 'Why?',\nHe replied with a cry,\n'My clock always wakes me at eight.'\n\nThere was an old man from Jaipur\nWhose house had a green and blue door.\nI said, 'I like white.'\nHe said, 'That's all right,\nBut I think that white is a bore.'"
