            "text": "Unit 3 Transcripts (continued)\n\nLesson 3 Booking lessons\nA. Listen and read. Fill in part of the timetable in your Activity Book.\nPart 1\nLiz: Hello. Is that the sports centre?\nSports officer: Yes. Can I help you?\nLiz: Well, I'd like to play volleyball.\nSports officer: How good are you at volleyball?\nLiz: Oh, I'm quite good. I'm in the school team.\nSports officer: All right. Come on Monday at seven o'clock. It's team practice.\nLiz: Thanks very much. Oh, and I'd like to learn horse riding.\nSports officer: We have beginners' lessons on Wednesdays at five o'clock.\nLiz: Thank you very much. Goodbye.\n\nPart 2\nSports officer: Hello. Sports centre.\nDave: Hello. I'd like to do judo.\nSports officer: Are you good at judo, or do you want to learn?\nDave: I'm a beginner. I want to learn.\nSports officer: That's fine. Beginners' lessons are on Tuesdays at five o'clock.\n\n1. Listen and fill in some more of the timetable.\nPart 1\nSports officer: Sports centre. Can I help you?\nGirl: Yes. I'd like to join a gymnastics lesson. When is it, please?\nSports officer: Are you good at gymnastics, or do you want to learn?\nGirl: Oh, I want to learn. I've never done gymnastics before.\nSports officer: Well, the beginners' lesson for girls is on Wednesday at seven o'clock.\n\nPart 2\nBoy 1: Hello. Is that the sports centre?\nSports officer: Yes. Can I help you?\nBoy 1: Yes. I want to go swimming. Can you tell me when lessons are?\nSports officer: How good are you at swimming?\nBoy 1: I'm quite a good swimmer. I'd like to try to join the team.\nSports officer: Right. Team practice is on Thursday at seven o'clock.\nBoy 1: Thursday at seven o'clock. Thank you.\n\nPart 3\nSports officer: Sports centre. Can I help you?\nBoy 2: Yes. I want to do horse riding lessons. I'm quite good, but I want to improve.\nSports officer: Our advanced lessons are on Saturdays at ten in the morning. Can you come then?\nBoy 2: Yes, I can. That's fine. Thank you.\n\nLesson 4 The basketball game\nC. Listen and check.\n1f, 2c, 3a, 4d, 5b, 6e\n\nD. Listen. Practise the conversation with your partner.\nHilal: Samir. That was awful! How did we lose?\nSamir: It was my fault, Hilal. I was terrible!\nHilal: You? At least you won a few points.\nSamir: What? You won more points than I did. You always do. Let's face it. We're not very fit.\nHilal: I know. Other people are fitter than us. And they can run faster. They can beat us at anything.\nSamir: What can we do? We have to get fitter.\nHilal: Let's have a competition. Just you against me.\nSamir: Good idea! We'll have a 100-metre race, a swimming race, and we'll do the high jump.\nHilal: High jump! But I jumped higher than you last week.\nSamir: That wasn't in a competition. When shall we have it?\nHilal: Next weekend. Swimming, running and high jump. OK?\nSamir: OK. I'll see you next weekend at the sports centre."
