            "text": "Unit 3 Transcripts (continued)\n\nLesson 8 Have fun with words!\nA. Listen and say.\nShe sells seashells on the seashore.\nThe shells she sells are seashells, I'm sure.\n\nB. Listen and try saying another one.\nPeter Piper pecked a pot of pickled pepper.\n\nStory time Jad and Johnny – The football match\nA. Listen, read and find out.\nFor the story text, see pages 37–38.\n\nProject 2 The sports survey\nA. Umar and Ali are talking about sport. Listen and answer the questions.\nUmar: Do you do much sport, Ali?\nAli: Yeah, I do quite a lot. I play basketball once a week.\nUmar: Um ... that's not very much.\nAli: I think it is. I think most people in our class do sport once a week.\nUmar: No! I think they do some sport every day.\nAli: I have an idea. Let's do a survey and find out.\nUmar: A survey ... What's that?\nAli: We write some questions, and we ask everyone in the class. Then we write down their answers and look at the results.\nUmar: OK, that sounds fun. Let's write some questions ...\n\nB. Look at Umar and Ali's notes and complete their survey questions. Listen and check.\nQuestion one. What sports do you do?\nQuestion two. What is your favourite sport?\nQuestion three. How often do you do sport?\nQuestion four. Which new sport would you like to try?\n\nE. Umar and Ali are presenting the results of their survey to the class. Look at the two charts and answer the questions. Listen and check your answers.\nUmar: Hello everyone. These are the results of our class survey about sport. First, we asked the question, 'What is your favourite sport?'. As you can see, football is the most popular sport in the class. Then it's volleyball, then swimming, then basketball, then karate. Finally, it's tennis. So, tennis is the least popular sport in the class.\nAli: Our next question was 'Which new sport would you like to try?', and this chart shows the results. Nine people would like to try surfing. Seven people would like to try Ultimate. Thirteen people would like to try skateboarding. Finally, seven people don't want to try any of these new sports."
