            "text": "Unit 4 Review\n\nLesson 1 Listening\nB. Listen to two conversations.\nConversation 1\nMan 1: Can you pass me a magazine, please?\nMan 2: This one?\nMan 1: Yeah. Thanks.\nMan 2: How long have you been here?\nMan 1: Half an hour. I came in just five minutes before you.\nMan 2: Why do we always have to wait so long? They should know that we have to work, too. I don't have time to sit here.\nMan 1: No, I don't either. I came in here with an earache. Now I have a headache as well. What about you?\nMan 2: Pain in my back. Sitting on chairs like these doesn't help. What is the doctor doing? Is it worth waiting? He'll give us pills and tell us to rest.\n\nConversation 2\nMan: It's nice here, isn't it?\nWoman: Yes, it's new. It's only been open a week.\nMan: What's yours like?\nWoman: Delicious. What did you order?\nMan: The chicken with orange sauce.\nWoman: It looks interesting.\nMan: It's all right. Nothing fantastic.\nWoman: Do you want some more water?\nMan: Yes, please.\nWoman: Waiter!\n\nC. You want to know the score in a football match between Iraq and Bahrain. Listen to the radio.\nAnnouncer: And now, sport. At the end of an exciting game at the new National Stadium, the score was Iraq 3, Bahrain 3.\n\nD. Work out the student notes below. Then listen and check.\nWaiter: Are you ready to order now, sir?\nMr Andrews: Yes, we are. I'd like fried chicken with – er – rice, please.\nWaiter: Salad?\nMr Andrews: Er – salad – do I want salad? Yes, please.\nWaiter: Madam?\nMrs Andrews: Er, grilled fish, please. With fries. And I'll have salad, too.\nWaiter: Grilled fish, fries and salad. And dessert?\nMrs Andrews: Fruit salad, please.\nMr Andrews: And chocolate cake for me.\nWaiter: One chocolate cake and one fruit salad. Anything to drink?\nMr Andrews: Apple juice for me.\nMrs Andrews: And mineral water for me.\nWaiter: Apple juice and mineral water. Thank you, madam, sir.\n\n1. Listen and answer the questions.\nTeacher: Come in, Wendy. Don't be shy. Sit down.\nWendy: Thank you.\nTeacher: Now, what is it?\nWendy: Well – I can't sleep at night, and I get headaches all the time.\nTeacher: Are you worried about something? School? Exams?\nWendy: No, no. Nothing like that. I'm doing very well at school. And I never worry about exams. It's just that I can't sleep, and then in the morning, I have a headache. Always. Every morning.\nTeacher: Mm. Have you been to a doctor?\nWendy: No. My parents won't take me. They don't think I have a problem.\nTeacher: Do you take any pills?\nWendy: No. When I take pills, I get a stomach ache.\nTeacher: I see. You get a stomach ache. Er – what time do you eat in the evening?\nWendy: We have dinner at about 7:30, and then I have a glass of lemonade and a packet of crisps just before I go to bed. At about ten o'clock."
