            "text": "Unit 1 Extra activities\n\n2. Listen. Match the person (a–f) to the section (1–6) they will write for their school magazine.\nNadia: Right. The interview. We need somebody to do the interview. Would you like to interview somebody, Maysam?\nMaysam: Me? No. I can't do that, Nadia. I'm doing the problem page.\nNadia: Oh, yes. Of course you are. Maysam – Problem page. But we still need somebody to do the interview.\nMaysam: How about Tanya? She likes talking to people. And she writes well.\nNadia: OK. Good idea. Tanya – Interview. What's next?\nMaysam: Um – the story. We don't have a story yet.\nNadia: Don't we? Oh, dear. Well, I'll write the story. It'll be quicker if I do it. OK with you?\nMaysam: Fine. But will you have time, Nadia?\nNadia: Sure. I'll do it. Nadia – Story. Now – who wrote about school news last time?\nMaysam: Just a minute. Um, School news – Rasha. But she doesn't want to do it again. She told me. She wants to write a review of a TV programme.\nNadia: Well, if she really wants to, I don't mind. Rasha – TV review. But who'll do the school news then?\nMaysam: I think Mona wants to do the school news this time. She asked me.\nNadia: OK. Mona – School news. That leaves just the sports news. Who's interested in sport?\nMaysam: Abla. She loves sport.\nNadia: Yes. But is she good at English?\nMaysam: Abla? Of course. She's fantastic at English.\nNadia: Well, Abla it is, then. Abla – Sports news. I think that's it.\nMaysam: Right. Let's go and get something to drink.\n\nUnit 3 Extra activities\n\n1. Listen. Which classes are going to be in the Sports Weekend? Write Y for 'yes', and N for 'no'. Then fill in the timetable.\nMale: Right – shall we try and do the timetable for the Sports Weekend?\nFemale: I've done one. Do you want to have a look at it?\nMale: Fantastic! Let me see. Now, on Saturday, we have only beginners' classes and on Sunday, only advanced classes? Is that right?\nFemale: Yes. And we start with karate. Karate beginners – Saturday, from ten o'clock to twelve o'clock.\nMale: And the advanced class is – let me see now – Sunday, from two o'clock to four o'clock. Fine.\nFemale: Next, tennis. Advanced classes only. We have no beginners. Sunday evening, from five o'clock to seven o'clock.\nMale: No beginners at tennis?\nFemale: No. Everybody is advanced. But for athletics, we only have a beginners' class. That's on Saturday, from two o'clock to four o'clock.\nMale: That leaves just two classes.\nFemale: That's right. And they'll be gymnastics.\nMale: No judo or swimming or horse riding or ...?\nFemale: No. There's no time. So, gymnastics – beginners. Saturday, from five o'clock to seven o'clock. And advanced ...\nMale: Let me guess. Sunday morning, from ten o'clock to twelve o'clock.\nFemale: Correct. Sunday. Ten to twelve. Advanced gymnastics.\nMale: So, let's check that. Karate beginners – Saturday, ten to twelve. Karate advanced – Sunday, two to four. Tennis – advanced only – Sunday, from five to seven. Athletics, beginners only – Saturday, two o'clock to four o'clock. And gymnastics, beginners – Saturday evening, five to seven. And advanced – Sunday, from ten o'clock in the morning to twelve. Fine."
