            "text": "Unit 5 Getting and sending information\n\nLesson 2 Accessing information\n2. Three people need information. Listen to their conversations and fill in the table.\n\nPart 1\nIbrahim: Hi, Saad.\nSaad: Hello, Ibrahim. I've got a problem.\nIbrahim: What's the problem?\nSaad: I want to go fishing tomorrow, but I don't know what the weather will be like.\nIbrahim: You should listen to the weather forecast on the radio.\nSaad: Oh, yes. Good idea.\n\nPart 2\nMaysam: Hi, Badria. I've got a problem.\nBadria: What is it? Maybe I can help.\nMaysam: I have to write about a famous Iraqi inventor for the magazine. Where can I find some information?\nBadria: Use the internet.\nMaysam: I've tried, but I can't find anything.\nBadria: Go to the reference section in the library then. You'll probably find some information there.\nMaysam: I'll do that. Thanks.\n\nPart 3\nBilal: Hello, Bilal here.\nKhalid: Hi, Bilal. This is Khalid. Let's go to the cinema tonight.\nBilal: Oh, fine, yes. What's on?\nKhalid: Oh, I don't know what's on. I phoned the cinema, but there's no reply.\nBilal: Have you got a newspaper?\nKhalid: A newspaper? Yes.\nBilal: Well, use it! Look at the 'What's on' section. You'll find the cinema listings there.\nKhalid: Oh, OK. I'll call you back.\n\nLesson 8 Making telephone calls\nB. Listen to Anas on the telephone and look at Susan's advice. What does he do wrong?\nReceptionist: Baghdad Medical Centre. How can I help you?\nAnas: Ahhh, my stomach, my stomach!\nReceptionist: Hold on. Hold on. Who's speaking, please?\nAnas: Oh. Yes. Um. Sorry. My name is Anas. And, it really hurts.\nReceptionist: Excuse me, what are you talking about? What hurts?\nAnas: Er, my stomach. I have a bad stomach ache.\nReceptionist: Oh, OK. Are you registered at the medical centre?\nAnas: I don't know. I need to see a doctor.\nReceptionist: What is your family name? I can check to see if you are registered.\nAnas: (Muffled) Abdullah.\nReceptionist: I'm sorry. Could you repeat that, please?\nAnas: Abdullah. Anas Abdullah.\nReceptionist: Can you spell that, please?\nAnas: A-B-D-U-L-L-A-H.\nReceptionist: OK. Yes, you are registered. How long has your stomach been hurting?\nAnas: For days now. I can't remember. Since Tuesday? No, since Monday after my dinner.\nReceptionist: OK. So, for three days? Right, when can you come to see the doctor?\nAnas: I can come any time. Well, actually, I can't come until my mum gets home so she can drive me.\nReceptionist: And what time is that?\nAnas: Four o'clock.\nReceptionist: OK. I have an appointment at 4:30. Would that be OK?\nAnas: Yes, thank you. That would be great.\nReceptionist: OK. We'll see you at 4:30.\nAnas: Thanks, bye."
