            "text": "Unit 5 Transcripts (continued)\n\n1. Listen to Anas making an appointment. This time, he is following Susan's advice. Write notes.\nReceptionist: Baghdad Medical Centre. How can I help you?\nAnas: Hi. My name's Anas Abdullah. I need to book an appointment to see a doctor. I have a stomach ache.\nReceptionist: OK. Are you registered with us, Anas?\nAnas: Yes, I've been before. My family name is Abdullah.\nReceptionist: Could you spell that, please?\nAnas: Yes, of course. A-B-D-U-L-L-A-H.\nReceptionist: Thanks. How long have you had your stomach ache?\nAnas: Um, around three days now.\nReceptionist: OK, you'd better come in today. When would you like an appointment?\nAnas: Any time after four, please.\nReceptionist: I have an appointment at 4:30. Would that be OK?\nAnas: Yes, thank you.\nReceptionist: See you at 4:30.\n\nStory time Jad and Johnny – The gondola trip\nA. Listen, read and find out.\nFor the story text, see pages 56–57.\n\nUnit 6 Jobs\n\nLesson 1 What do they do?\nA. Listen and read the descriptions. Then match them to the photographs.\na. A businesswoman works in an office and runs a business. She is very good at working with money.\nb. A pilot flies a plane and takes people to different countries. They have to wear a uniform.\nc. An architect plans and designs buildings. They work in an office.\nd. A mechanic works in a workshop or a garage and repairs people's cars.\ne. An engineer works outside or in an office. They design, build or repair machines, roads and bridges.\nf. A shop assistant works for a shopkeeper or shop owner. They help customers, the people who want to buy things in the shop.\ng. A firefighter's job is very dangerous. They put out fires and save people. A firefighter has to wear special clothes.\n\nLesson 2 Two jobs\n4. Now listen and check.\nVoice: Where do you work?\nNurse: I work at the Red Crescent Hospital.\nVoice: Do you have to wear a uniform at work?\nNurse: Yes. I have to wear a uniform at work.\nVoice: Do you like your job?\nNurse: Yes. I like my job very much.\nVoice: How long do you have to work?\nNurse: Oh, I usually have to work ten hours a day.\nVoice: Is it hard work?\nNurse: Yes. It's very hard work, but I like taking care of sick people."
