            "heading": "Transcripts: Unit 6 (Lessons 2–4, p. 102)",
            "text": "Unit 6 Transcripts (continued)\n\nVoice: How long did you have to study?\nNurse: I had to study for four years.\nVoice: Do you want to be a doctor?\nNurse: No, I don't want to be a doctor. I love my job.\nVoice: How many people do you see every day?\nNurse: Every day? Oh, I usually see about 40 or 50 people every day.\n\nLesson 3 A day in the life of a firefighter\n2. Listen and check your answers.\nFirefighter: When I arrived at the fire station yesterday morning, I checked my equipment as usual. We had our first call at ten o'clock. We were told there was a fire in a supermarket in the middle of town. We drove through the streets as fast as possible. When we got there, the fire was burning strongly. The heat was terrible, and some people were trapped inside. We had to get them out quickly. We got out our hoses and pointed them at the building. Twenty minutes later, the fire was out, and we were able to go into the building. We saved all the people, but some had to go to hospital.\nAt two o'clock, we were called to an accident on the ring road. The police helped us get there very fast. One car was on fire and another was upside down on the road. Fortunately, the driver of the burning car was standing by the side of the road. However, the driver of the other car was trapped. We put the fire out quickly and got the second driver out. He was badly injured.\nAt the end of the day, I was tired and upset about the accident. But it's all in a day's work for a firefighter. We do our best.\n\nLesson 4 What's my job?\nB. Listen and answer the questions.\nPart 1\nTeacher: Good morning, class.\nClass: Good morning, Miss Hadeel.\nTeacher: Today you're going to play a game.\nClass: (Slight cheer)\nTeacher: The name of this game is 'What's my job?', and this is what I want you to do. You'll work in pairs. One of you, Student 1, thinks of a job but doesn't tell her partner. OK?\nClass: Yes, Miss Hadeel.\nTeacher: Student 2 has to try to find out what the job is. Student 2 can ask five questions – only five, no more. If you can find out the job with five questions or fewer, you get a point. If not – nothing. Right. You can begin. I'll listen.\nStudent 2: Have you thought of a job?\nStudent 1: Yes.\nStudent 2: Um – do you work inside?\nStudent 1: Sometimes.\nStudent 2: Do you work in an office?\nStudent 1: No.\nStudent 2: Do you make food for people?\nStudent 1: No.\nStudent 2: Do you help people?\nStudent 1: Yes.\nStudent 2: You're a doctor.\nStudent 1: Wrong. I'm a police officer.\n\nPart 2\nTeacher: Good morning, class.\nClass: Good morning, Mr Kareem.\nTeacher: Right, everybody. Today I want you to play a game.\nClass: (Slight cheer)\nTeacher: The name of this game is 'What's my job?', and this is what I want you to do. You'll work in pairs. One of you, Student 1, thinks of a job but doesn't tell her partner. All right?\nClass: Yes, Mr Kareem.\nTeacher: Student 2 has to guess what the job is. Student 1 says five things about the job, and after each sentence, Student 2 makes a guess. Remember – only five things,"
