            "text": "Unit 7 Extra activities\n\n1. Listen to some boys and answer the questions.\nYassir: Phew! I'm hot. That was a long walk. Let's sit down and have something to drink.\nJamal: Good idea! Do you want a bottle of water or a can of cola? (Pause) Yassir! You aren't listening. What's wrong?\nYassir: Just look at that, Jamal!\nJamal: What?\nYassir: All that rubbish lying around on the beach.\nJamal: Hm, yes. Some litter louts must have been on the beach.\nYassir: It's horrible. We must do something.\nJamal: Do something? What can we do?\nYassir: Pick it up.\nJamal: You're joking! Why should we pick it up? We didn't put it there.\nYassir: I know, but if we don't do something, who will? Come on, Jamal. You know we've all been asked to try to keep our country clean. Here's your chance.\nJamal: Oh! Well! All right!\nYassir: Good! You collect bottles and cans. I'll collect paper.\nJamal: What do I collect them in?\nYassir: There are plenty of plastic bags lying around. Use some of them.\nJamal: I thought you were thirsty, Yassir. What about that drink you wanted?\nYassir: I'll have it later. I'll be even thirstier after picking up this lot.\nJamal: Well, I'm having some water now and when I've finished.\nYassir: (Laughing) OK, Jamal! Have some water and cheer up! Don't be so grumpy. You'll feel fantastic when you've finished!\nJamal: Hm, maybe. But I came to the beach to enjoy myself, not to work."
